)

type volumeStruct struct {
	volumeName                string
	mountpointDirPath         string
	fuseSubtype               string
	maxRead                   uint32
	maxWrite                  uint32
	defaultPermissions        bool
	allowOther                bool
	numWorkers                int
	perWorkerFD               bool
	callbacks                 Callbacks
	logger                    *log.Logger
	errChan                   chan error
	errChanOnce               sync.Once
	devFuseFDReadSize         uint32 // InHeaderSize + WriteInSize + InitOut.MaxWrite
	devFuseFD                 int
	devFuseFile               *os.File
	devFuseFDReaderWG         sync.WaitGroup
	devFuseFDReaderBlockedSet sync.Map
	fuseMajor                 uint32
	fuseMinor                 uint32
	doInitWG                  sync.WaitGroup
}

const (
	recvmsgFlags   = int(0)
	recvmsgOOBSize = 32
	recvmsgPSize   = 4

	devLinuxFusePath = "/dev/fuse"

	devFuseFDReadSizeMin = 2 * 4096
)

func newVolume(volumeConfig *VolumeConfig) (volume *volumeStruct) {
	var (
		devFuseFDReadSize uint32
	)

	// Note: The following assumes maxWrite is either zero (indicating a ReadOnly Volume)
	//       or sufficiently large to make the WriteIn case the largest message possible
	//
	devFuseFDReadSize = InHeaderSize + WriteInFixedPortionSize + volumeConfig.MaxWrite
	if devFuseFDReadSize < devFuseFDReadSizeMin {
		devFuseFDReadSize = devFuseFDReadSizeMin
	}

	volume = &volumeStruct{
		volumeName:         volumeConfig.VolumeName,
		mountpointDirPath:  volumeConfig.MountpointDirPath,
		fuseSubtype:        volumeConfig.FuseSubtype,
		maxRead:            volumeConfig.MaxRead,
		maxWrite:           volumeConfig.MaxWrite,
		defaultPermissions: volumeConfig.DefaultPermissions,
		allowOther:         volumeConfig.AllowOther,
		// numWorkers filled in below
		perWorkerFD:       volumeConfig.PerWorkerFD,
		callbacks:         volumeConfig.Callbacks,
		logger:            volumeConfig.Logger,
		errChan:           volumeConfig.ErrChan,
		devFuseFDReadSize: devFuseFDReadSize,
		fuseMajor:         0,
		fuseMinor:         0,
	}

	if volumeConfig.NumWorkers == 0 {
		volume.numWorkers = runtime.NumCPU()
	} else {
		volume.numWorkers = volumeConfig.NumWorkers
	}

	return
}

func (volume *volumeStruct) DoMount() (err error) {
	var (
		childOpenFDs             []int
		fsnameOption             string
		fuseSubtypeOption        string
		fusermountChildWriteFile *os.File
		fusermountLineCount      uint32
		fusermountParentReadFile *os.File
		fusermountProgramPath    string
		fusermountSocketPair     [2]int
		gid                      int
		gidOption                string
		maxReadOption            string
		mountCmd                 *exec.Cmd
		mountCmdStderrPipe       io.ReadCloser
		mountCmdStdoutPipe       io.ReadCloser
		mountOptions             string
		recvmsgOOB               [recvmsgOOBSize]byte
		recvmsgOOBN              int
		recvmsgP                 [recvmsgPSize]byte
		rootMode                 uint32
		rootModeOption           string
		scanPipeWaitGroup        sync.WaitGroup
		socketControlMessages    []syscall.SocketControlMessage
		syscallRecvmsgAborted    bool
		uid                      int
		uidOption                string
		unmountCmd               *exec.Cmd
	)

	fusermountProgramPath, err = exec.LookPath("fusermount")
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() unable to find program `fusermount`: %v", volume.volumeName, err)
		return
	}

	unmountCmd = exec.Command(fusermountProgramPath, "-u", volume.mountpointDirPath)
	_, _ = unmountCmd.CombinedOutput()

	fusermountSocketPair, err = syscall.Socketpair(syscall.AF_UNIX, syscall.SOCK_SEQPACKET, 0)
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() unable to create socketpairFDs: %v", volume.volumeName, err)
		return
	}

	fusermountChildWriteFile = os.NewFile(uintptr(fusermountSocketPair[0]), "fusermountChildWriteFile")
	fusermountParentReadFile = os.NewFile(uintptr(fusermountSocketPair[1]), "fusermountParentReadFile")

	syscallRecvmsgAborted = false

	defer func() {
		var (
			localErr error
		)

		if !syscallRecvmsgAborted {
			localErr = fusermountChildWriteFile.Close()
			if localErr != nil {
				volume.logger.Printf("Volume %s DoMount() unable to close fusermountChildWriteFile: %v", volume.volumeName, err)
			}
		}

		localErr = fusermountParentReadFile.Close()
		if localErr != nil {
			volume.logger.Printf("Volume %s DoMount() unable to close fusermountParentReadFile: %v", volume.volumeName, err)
		}
	}()

	rootMode = syscall.S_IFDIR
	rootModeOption = fmt.Sprintf("rootmode=%o", rootMode)

	uid = syscall.Geteuid()
	gid = syscall.Getegid()

	uidOption = fmt.Sprintf("user_id=%d", uid)
	gidOption = fmt.Sprintf("group_id=%d", gid)
	fsnameOption = "fsname=" + volume.volumeName
	maxReadOption = fmt.Sprintf("max_read=%d", volume.maxRead)

	mountOptions = rootModeOption +
		"," + uidOption +
		"," + gidOption +
		"," + fsnameOption +
		"," + maxReadOption

	if volume.maxWrite == 0 {
		mountOptions += ",ro"
	} else {
		mountOptions += ",rw"
	}

	if volume.defaultPermissions {
		mountOptions += ",default_permissions"
	}
	if volume.allowOther {
		mountOptions += ",allow_other"
	}

	if volume.fuseSubtype != "" {
		fuseSubtypeOption = "subtype=" + volume.fuseSubtype
		mountOptions += "," + fuseSubtypeOption
	}

	mountCmd = &exec.Cmd{
		Path: fusermountProgramPath,
		Args: []string{
			fusermountProgramPath,
			"-o", mountOptions,
			"--", volume.mountpointDirPath,
		},
		Env:          append(os.Environ(), "_FUSE_COMMFD=3"),
		Dir:          "",
		Stdin:        nil,
		Stdout:       nil, // This will be redirected to mountCmdStdoutPipe below
		Stderr:       nil, // This will be redirected to mountCmdStderrPipe below
		ExtraFiles:   []*os.File{fusermountChildWriteFile},
		SysProcAttr:  nil,
		Process:      nil,
		ProcessState: nil,
	}

	scanPipeWaitGroup.Add(2)

	mountCmdStdoutPipe, err = mountCmd.StdoutPipe()
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() unable to create mountCmd.StdoutPipe: %v", volume.volumeName, err)
		return
	}

	go volume.scanPipe("mountCmdStdoutPipe", mountCmdStdoutPipe, nil, &scanPipeWaitGroup)

	mountCmdStderrPipe, err = mountCmd.StderrPipe()
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() unable to create mountCmd.StderrPipe: %v", volume.volumeName, err)
		return
	}

	go volume.scanPipe("mountCmdStderrPipe", mountCmdStderrPipe, &fusermountLineCount, &scanPipeWaitGroup)

	volume.doInitWG.Add(1)

	err = mountCmd.Start()
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() unable to mountCmd.Start(): %v", volume.volumeName, err)
		return
	}

	go volume.awaitScanPipe(&scanPipeWaitGroup, &fusermountLineCount, &syscallRecvmsgAborted, fusermountChildWriteFile)

	_, recvmsgOOBN, _, _, err = syscall.Recvmsg(
		int(fusermountParentReadFile.Fd()),
		recvmsgP[:],
		recvmsgOOB[:],
		recvmsgFlags)
	if syscallRecvmsgAborted {
		err = fmt.Errorf("Volume %s DoMount() failed", volume.volumeName)
		return
	}
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() got error from fusermount: %v", volume.volumeName, err)
		return
	}

	socketControlMessages, err = syscall.ParseSocketControlMessage(recvmsgOOB[:recvmsgOOBN])
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() unable to syscall.ParseSocketControlMessage(): %v", volume.volumeName, err)
		return
	}
	if len(socketControlMessages) != 1 {
		volume.logger.Printf("Volume %s DoMount() got unexpected len(socketControlMessages): %v", volume.volumeName, len(socketControlMessages))
		return
	}

	childOpenFDs, err = syscall.ParseUnixRights(&socketControlMessages[0])
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() unable to syscall.ParseUnixRights(): %v", volume.volumeName, err)
		return
	}
	if len(childOpenFDs) != 1 {
		volume.logger.Printf("Volume %s DoMount() got unexpected len(childOpenFDs): %v", volume.volumeName, len(childOpenFDs))
		return
	}

	volume.devFuseFD = childOpenFDs[0]
	volume.devFuseFile = os.NewFile(uintptr(volume.devFuseFD), devLinuxFusePath)

	if volume.numWorkers <= 0 {
		// Note that if volumeConfig.NumWorkers was zero, volume.numWorkers will be runtime.NumCPU() that is always positive
		volume.logger.Printf("Volume %s DoMount() found negative NumWorkers: %v", volume.volumeName, volume.numWorkers)
		return
	}

	volume.devFuseFDReaderWG.Add(volume.numWorkers)

	for range volume.numWorkers {
		go volume.devFuseFDReader()
	}

	err = mountCmd.Wait()
	if err != nil {
		volume.logger.Printf("Volume %s DoMount() got error from fusermount: %v", volume.volumeName, err)
		return
	}

	volume.doInitWG.Wait()

	volume.logger.Printf("Volume %s mounted on mountpoint %s", volume.volumeName, volume.mountpointDirPath)

	err = nil
	return
}

func (volume *volumeStruct) DoUnmount() (err error) {
	var (
		fusermountProgramPath    string
		unmountCmd               *exec.Cmd
		unmountCmdCombinedOutput []byte
	)

	fusermountProgramPath, err = exec.LookPath("fusermount")
	if err != nil {
		volume.logger.Printf("DoUnmount() unable to find program `fusermount`: %v", err)
		return
	}

	unmountCmd = exec.Command(fusermountProgramPath, "-u", "-q", "-z", "--", volume.mountpointDirPath)
	unmountCmdCombinedOutput, err = unmountCmd.CombinedOutput()
	if err != nil {
		volume.logger.Printf("DoUnmount() unable to unmount %s (%v): %s", volume.volumeName, err, string(unmountCmdCombinedOutput))
		return
	}

	volume.devFuseFDReaderWG.Wait()

	err = volume.devFuseFile.Close()
	if err != nil {
		volume.logger.Printf("DoUnmount() unable to close %s: %v", devLinuxFusePath, err)
		return
	}

	volume.logger.Printf("Volume %s unmounted from mountpoint %s", volume.volumeName, volume.mountpointDirPath)

	err = nil
	return
}

func (volume *volumeStruct) HighLatencyCallback(inHeader *InHeader) {
	var (
		wasSubstitutedAlready bool
	)

	_, wasSubstitutedAlready = volume.devFuseFDReaderBlockedSet.Load(inHeader)
	if !wasSubstitutedAlready {
		volume.devFuseFDReaderBlockedSet.Store(inHeader, struct{}{})
		volume.devFuseFDReaderWG.Add(1)
		go volume.devFuseFDReader()
	}
}

func (volume *volumeStruct) scanPipe(name string, pipe io.ReadCloser, lineCount *uint32, wg *sync.WaitGroup) {
	var (
		pipeScanner *bufio.Scanner = bufio.NewScanner(pipe)
	)

	for pipeScanner.Scan() {
		if lineCount != nil {
			atomic.AddUint32(lineCount, 1)
		}
		volume.logger.Printf("Volume %s DoMount() %s: %s", volume.volumeName, name, pipeScanner.Text())
	}

	wg.Done()
}

func (volume *volumeStruct) awaitScanPipe(wg *sync.WaitGroup, lineCount *uint32, syscallRecvmsgAborted *bool, fusermountChildWriteFile *os.File) {
	var (
		err error
	)

	wg.Wait()

	if *lineCount != 0 {
		*syscallRecvmsgAborted = true

		volume.logger.Printf("Volume %s DoMount() got error(s) from fusermount - exiting", volume.volumeName)

		err = syscall.Close(int(fusermountChildWriteFile.Fd()))
		if err != nil {
			volume.logger.Printf("DoMount() unable to close fusermountChildWriteFile: %v", err)
		}
	}
}

func (volume *volumeStruct) devFuseFDReader() {
	var (
		bytesRead             int
		devFuseFDClone        int
		devFuseFDCloneWrapped *os.File
		devFuseFDReadBuf      = make([]byte, volume.devFuseFDReadSize)
		err                   error
		wasSubstituted        bool
	)

	if volume.perWorkerFD {
		devFuseFDClone, err = unix.Open(devLinuxFusePath, unix.O_RDWR, 0)
		if err != nil {
			volume.errChanOnce.Do(func() {
				volume.logger.Printf("Exiting due to %s Open err: %v", devLinuxFusePath, err)
				volume.errChan <- err
			})

			volume.devFuseFDReaderWG.Done()

			return
		}

		err = unix.IoctlSetPointerInt(devFuseFDClone, FuseDevIocClone, volume.devFuseFD)
		if err != nil {
			volume.errChanOnce.Do(func() {
				volume.logger.Printf("Exiting due to %s IoctlSetInt err: %v", devLinuxFusePath, err)
				volume.errChan <- err
			})

			_ = syscall.Close(devFuseFDClone)

			volume.devFuseFDReaderWG.Done()

			return
		}

		err = unix.SetNonblock(devFuseFDClone, true)
		if err != nil {
			volume.errChanOnce.Do(func() {
				volume.logger.Printf("Exiting due to %s SetNonblock err: %v", devLinuxFusePath, err)
				volume.errChan <- err
			})

			_ = syscall.Close(devFuseFDClone)

			volume.devFuseFDReaderWG.Done()

			return
		}

		devFuseFDCloneWrapped = os.NewFile(uintptr(devFuseFDClone), "devFuseFDReader")
	} else {
		devFuseFDClone = volume.devFuseFD
		devFuseFDCloneWrapped = volume.devFuseFile
	}

	for {
		devFuseFDReadBuf = devFuseFDReadBuf[:volume.devFuseFDReadSize] // len == cap

		bytesRead, err = devFuseFDCloneWrapped.Read(devFuseFDReadBuf)
		if err != nil {
			if !errors.Is(err, io.EOF) && !errors.Is(err, syscall.EBADF) && !errors.Is(err, syscall.ENODEV) && !errors.Is(err, syscall.ENOTCONN) && !strings.Contains(err.Error(), "use of closed file") {
				// Report unexpected error

				volume.errChanOnce.Do(func() {
					volume.logger.Printf("Exiting due to %s Read() returning unexpected err: %v", devLinuxFusePath, err)
					volume.errChan <- err
				})
			}

			// In any event, it is time to exit

			if volume.perWorkerFD {
				_ = devFuseFDCloneWrapped.Close()
			}

			volume.devFuseFDReaderWG.Done()

			return
		}

		// Process devFuseFDReadBuf

		devFuseFDReadBuf = devFuseFDReadBuf[:bytesRead]

		wasSubstituted = volume.processDevFuseFDReadBuf(devFuseFDClone, devFuseFDReadBuf)
		if wasSubstituted {
			// Time to exit...

			if volume.perWorkerFD {
				_ = devFuseFDCloneWrapped.Close()
			}

			volume.devFuseFDReaderWG.Done()

			return
		}
	}
}

func (volume *volumeStruct) processDevFuseFDReadBuf(devFuseFDClone int, devFuseFDReadBuf []byte) (wasSubstituted bool) {
	var (
		inHeader *InHeader
	)

	if len(devFuseFDReadBuf) < InHeaderSize {
		// All we can do is just drop it
		volume.logger.Printf("Read malformed message from %s", devLinuxFusePath)
		wasSubstituted = false
		return
	}

	inHeader = &InHeader{
		Len:     *(*uint32)(unsafe.Pointer(&devFuseFDReadBuf[0])),
		OpCode:  *(*uint32)(unsafe.Pointer(&devFuseFDReadBuf[4])),
		Unique:  *(*uint64)(unsafe.Pointer(&devFuseFDReadBuf[8])),
		NodeID:  *(*uint64)(unsafe.Pointer(&devFuseFDReadBuf[16])),
		UID:     *(*uint32)(unsafe.Pointer(&devFuseFDReadBuf[24])),
		GID:     *(*uint32)(unsafe.Pointer(&devFuseFDReadBuf[28])),
		PID:     *(*uint32)(unsafe.Pointer(&devFuseFDReadBuf[32])),
		Padding: *(*uint32)(unsafe.Pointer(&devFuseFDReadBuf[36])),
	}

	switch inHeader.OpCode {
	case OpCodeLookup:
		volume.doLookup(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeForget:
		volume.doForget(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeGetAttr:
		volume.doGetAttr(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeSetAttr:
		volume.doSetAttr(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeReadLink:
		volume.doReadLink(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeSymLink:
		volume.doSymLink(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeMkNod:
		volume.doMkNod(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeMkDir:
		volume.doMkDir(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeUnlink:
		volume.doUnlink(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeRmDir:
		volume.doRmDir(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeRename:
		volume.doRename(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeLink:
		volume.doLink(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeOpen:
		volume.doOpen(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeRead:
		volume.doRead(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeWrite:
		volume.doWrite(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeStatFS:
		volume.doStatFS(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeRelease:
		volume.doRelease(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeFSync:
		volume.doFSync(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeSetXAttr:
		volume.doSetXAttr(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeGetXAttr:
		volume.doGetXAttr(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeListXAttr:
		volume.doListXAttr(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeRemoveXAttr:
		volume.doRemoveXAttr(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeFlush:
		volume.doFlush(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeInit:
		volume.doInit(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeOpenDir:
		volume.doOpenDir(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeReadDir:
		volume.doReadDir(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeReleaseDir:
		volume.doReleaseDir(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeFSyncDir:
		volume.doFSyncDir(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeGetLK:
		volume.doGetLK(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeSetLK:
		volume.doSetLK(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeSetLKW:
		volume.doSetLKW(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeAccess:
		volume.doAccess(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeCreate:
		volume.doCreate(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeInterrupt:
		volume.doInterrupt(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeBMap:
		volume.doBMap(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeDestroy:
		volume.doDestroy(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeIoCtl:
		volume.devFuseFDWriter(devFuseFDClone, inHeader, syscall.EINVAL)
	case OpCodePoll:
		volume.doPoll(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeBatchForget:
		volume.doBatchForget(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeFAllocate:
		volume.doFAllocate(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeReadDirPlus:
		volume.doReadDirPlus(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeRename2:
		volume.doRename2(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeLSeek:
		volume.doLSeek(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	case OpCodeStatX:
		volume.doStatX(devFuseFDClone, inHeader, devFuseFDReadBuf[InHeaderSize:])
	default:
		volume.devFuseFDWriter(devFuseFDClone, inHeader, syscall.ENOSYS)
	}

	_, wasSubstituted = volume.devFuseFDReaderBlockedSet.LoadAndDelete(inHeader)

	return
}

func (volume *volumeStruct) devFuseFDWriter(devFuseFDClone int, inHeader *InHeader, errno syscall.Errno, bufs ...[]byte) {
	var (
		buf          []byte
		bytesWritten uintptr
		iovec        []syscall.Iovec
		iovecSpan    uintptr
		outHeader    []byte
	)

	// First, log any syscall.ENOSYS responses

	if syscall.ENOSYS == errno {
		volume.logger.Printf("Read unsupported/unrecognized message OpCode == %v", inHeader.OpCode)
	}

	// Construct outHeader w/out knowing iovecSpan and put it in iovec[0]

	outHeader = make([]byte, OutHeaderSize)

	iovecSpan = uintptr(OutHeaderSize)

	*(*uint32)(unsafe.Pointer(&outHeader[0])) = uint32(iovecSpan) // Updated later
	*(*int32)(unsafe.Pointer(&outHeader[4])) = -int32(errno)
	*(*uint64)(unsafe.Pointer(&outHeader[8])) = inHeader.Unique

	iovec = make([]syscall.Iovec, 1, len(bufs)+1)

	iovec[0] = syscall.Iovec{Base: &outHeader[0], Len: uint64(OutHeaderSize)}

	// Construct iovec elements for supplied bufs (if any)

	for _, buf = range bufs {
		if len(buf) != 0 {
			iovec = append(iovec, syscall.Iovec{Base: &buf[0], Len: uint64(len(buf))})
			iovecSpan += uintptr(len(buf))
		}
	}

	// Now go back and update outHeader

	*(*uint32)(unsafe.Pointer(&outHeader[0])) = uint32(iovecSpan)

	// Finally, send iovec to devLinuxFusePath

RetrySyscallWriteV:
	bytesWritten, _, errno = syscall.Syscall(
		syscall.SYS_WRITEV,
		uintptr(devFuseFDClone),
		uintptr(unsafe.Pointer(&iovec[0])),
		uintptr(len(iovec)))
	if errno == 0 {
		if bytesWritten != iovecSpan {
			volume.logger.Printf("Write to %s returned bad bytesWritten: %v", devLinuxFusePath, bytesWritten)
		}
	} else {
		if errno == syscall.EINTR {
			goto RetrySyscallWriteV
		}
		if (errno == syscall.EAGAIN) || (errno == syscall.EWOULDBLOCK) {
			runtime.Gosched()
			goto RetrySyscallWriteV
		}
		volume.logger.Printf("Write to %s returned bad errno: %v", devLinuxFusePath, errno)
	}
}

func cloneByteSlice(inBuf []byte, andTrimTrailingNullByte bool) (outBuf []byte) {
	outBuf = make([]byte, len(inBuf))
	if len(inBuf) != 0 {
		_ = copy(outBuf, inBuf)
		if andTrimTrailingNullByte && (outBuf[len(outBuf)-1] == 0) {
			outBuf = outBuf[:len(outBuf)-1]
		}
	}
	return
}

